import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

export default function Editar() {
  const { id } = useParams();
  const navigate = useNavigate();

  const [formulario, setFormulario] = useState({
    nome: "",
    idade: "",
    rua: "",
    bairro: "",
    estado: "",
    biografia: "",
    imagem: "", // para exibir a imagem atual
  });

  const [foto, setFoto] = useState(null);

  useEffect(() => {
    const buscarUsuario = async () => {
      try {
        const resposta = await axios.get(`http://localhost:3001/usuarios/${id}`);
        setFormulario({
          nome: resposta.data.nome,
          idade: resposta.data.idade,
          rua: resposta.data.rua,
          bairro: resposta.data.bairro,
          estado: resposta.data.estado,
          biografia: resposta.data.biografia,
          imagem: resposta.data.imagem,
        });
      } catch (erro) {
        console.error("Erro ao carregar dados:", erro);
      }
    };

    buscarUsuario();
  }, [id]);

  const handleChange = (e) => {
    setFormulario({ ...formulario, [e.target.name]: e.target.value });
  };

  const handleFotoChange = (e) => {
    setFoto(e.target.files[0]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const dados = new FormData();
    dados.append("nome", formulario.nome);
    dados.append("idade", formulario.idade);
    dados.append("rua", formulario.rua);
    dados.append("bairro", formulario.bairro);
    dados.append("estado", formulario.estado);
    dados.append("biografia", formulario.biografia);
    if (foto) dados.append("foto", foto);

    try {
      await axios.put(`http://localhost:3001/usuarios/${id}`, dados);
      alert("Usuário atualizado com sucesso!");
      navigate(`/usuarios/${id}`);
    } catch (erro) {
      console.error("Erro ao atualizar usuário:", erro);
      alert("Erro ao atualizar.");
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Editar Usuário</h2>

      {formulario.imagem && (
        <img
          src={`http://localhost:3001${formulario.imagem}`}
          alt="Foto atual"
          style={{ width: 150, marginBottom: 20, borderRadius: 10 }}
        />
      )}

      <form onSubmit={handleSubmit}>
        <input name="nome" value={formulario.nome} onChange={handleChange} placeholder="Nome" required />
        <input name="idade" value={formulario.idade} onChange={handleChange} placeholder="Idade" required />
        <input name="rua" value={formulario.rua} onChange={handleChange} placeholder="Rua" required />
        <input name="bairro" value={formulario.bairro} onChange={handleChange} placeholder="Bairro" required />
        <input name="estado" value={formulario.estado} onChange={handleChange} placeholder="Estado" required />
        <textarea name="biografia" value={formulario.biografia} onChange={handleChange} placeholder="Biografia" required />
        <input type="file" onChange={handleFotoChange} accept="image/*" />
        <button type="submit">Salvar Alterações</button>
      </form>
    </div>
  );
}
